package com.huy.enterprise.company;
import com.huy.enterprise.common.*; import com.huy.enterprise.common.enums.RecordStatus; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor @Transactional(readOnly=true) public class DepartmentService{private final DepartmentRepository repository;private final CompanyRepository companies;public List<DepartmentResponse> all(){return repository.findAll().stream().map(DepartmentResponse::from).toList();}@Transactional public DepartmentResponse create(DepartmentRequest r){if(repository.existsByCode(r.code()))throw new ConflictException("Department code already exists: "+r.code());Department d=new Department();d.setCode(r.code());apply(d,r);return DepartmentResponse.from(repository.save(d));}@Transactional public DepartmentResponse update(UUID id,DepartmentRequest r){Department d=get(id);if(!d.getCode().equals(r.code())&&repository.existsByCode(r.code()))throw new ConflictException("Department code already exists: "+r.code());d.setCode(r.code());apply(d,r);return DepartmentResponse.from(repository.save(d));}private Department get(UUID id){return repository.findById(id).orElseThrow(()->new ResourceNotFoundException("Department not found: "+id));}private void apply(Department d,DepartmentRequest r){d.setCompany(companies.findById(r.companyId()).orElseThrow(()->new ResourceNotFoundException("Company not found: "+r.companyId())));d.setName(r.name());d.setDescription(r.description());d.setStatus(r.status()==null?RecordStatus.ACTIVE:r.status());}}
